  /usr/bin/python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("properties",{{}}).get("ExecMainStatus","unknown"))' \"$REMOTE/unit-status-latest.json\" > \"$REMOTE/collector-exit.txt\"
