  echo COMPLETION_DIAGNOSTIC_TERMINAL_UPLOAD_ACK:\"$UNIT\"
elif test \"$LIFECYCLE\" = running; then
  echo COMPLETION_DIAGNOSTIC_RUNNING_ACK:\"$UNIT\"
