        ):
            with self.subTest(fragment=fragment):
                self.assertIn(fragment, script)
        self.assertNotIn("--scope", script)
        self.assertIsNone(re.search(r"(?:^|[;&|\s])(?:/usr/bin/)?timeout(?:\s|$)", script))
