		Detail:       name,
		Direction:    "callee_to_caller",
	}
}

func TestPunctuationPrefilteredReturnFlowsPreserveConditionalAndFallbackResults(t *testing.T) {
	tests := []struct {
		name  string
		block string
		want  []returnFlowCall
	}{
		{
			name: "ternary with tabs and nested arguments",
			block: "\treturn condition\t?\tprimary(inner(arg, other)) :\t" +
				"fallback(other(arg))\n",
			want: []returnFlowCall{conditionalReturnFlow("fallback"), conditionalReturnFlow("primary")},
		},
		{
			name:  "or fallback with nested arguments",
			block: "return primary(inner(arg, other)) || fallback(other(arg))\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
		{
			name:  "null-coalescing fallback with nested arguments",
			block: "return primary(inner(arg, other)) ?? fallback(other(arg))\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var got []returnFlowCall
			switch tt.name {
			case "ternary with tabs and nested arguments":
				got = ternaryReturnFlows(tt.block)
			default:
				got = fallbackReturnFlows(tt.block)
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("return-flow result = %#v, want %#v", got, tt.want)
			}
		})
	}
}

func TestPunctuationPrefilteredReturnFlowsSkipAbsentTriggerFamilies(t *testing.T) {
	block := "return direct(inner(arg, other))\n"
	if got := ternaryReturnFlows(block); got != nil {
		t.Fatalf("ternary flows for body without '?' = %#v, want nil", got)
	}
