package sem

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"sync"

	"github.com/entireio/entire-graph/internal/gitutil"
)

const defaultCaptureMemoryBytes int64 = 64 << 20

// capturedStore is operation-owned. It accepts only an already confined and
// bounded reader. It never makes a cache lookup an authorization to read a path.
// Integration with query lifetimes is deliberately separate from this primitive.
type capturedStore struct {
	attributeDecisionDigest string
	attributeDecisions      map[string]gitutil.CapturedDiffAttribute
	ctx                     context.Context
	cancel                  context.CancelFunc
	read                    contentReader
	limit                   int64
	mu                      sync.Mutex
	entries                 map[string]*captureEntry
	memory                  int64
	root                    *os.Root
	directory               string
	nextBacking             int
	closeDone               chan struct{}
	closed                  bool
	active                  sync.WaitGroup
	err                     error
	failure                 error
}

type captureEntry struct {
	policy  bool
	ready   chan struct{}
	source  capturedSource
	ok      bool
	backing string
	size    int64
	err     error
}

func newCapturedStore(ctx context.Context, read contentReader, memoryLimit int64) *capturedStore {
	ctx, cancel := context.WithCancel(ctx)
	if memoryLimit < 0 {
		memoryLimit = defaultCaptureMemoryBytes
	}
	return &capturedStore{ctx: ctx, cancel: cancel, read: read, limit: memoryLimit, entries: make(map[string]*captureEntry), closeDone: make(chan struct{})}
}

func (store *capturedStore) acquire(path string) (capturedSource, bool, error) {
	return store.acquireFrom(path, store.read)
}

func (store *capturedStore) acquireFrom(path string, read contentReader) (sourceResult capturedSource, available bool, resultErr error) {
	defer func() {
		if resultErr != nil {
			store.mu.Lock()
			if store.failure == nil {
				store.failure = resultErr
			}
			store.mu.Unlock()
		}
	}()
	store.mu.Lock()
	if store.closed {
		store.mu.Unlock()
		return capturedSource{}, false, os.ErrClosed
	}
	if err := store.ctx.Err(); err != nil {
		store.mu.Unlock()
		return capturedSource{}, false, err
	}
	entry, exists := store.entries[path]
	if !exists {
		entry = &captureEntry{ready: make(chan struct{})}
		store.entries[path] = entry
	}
	store.active.Add(1)
	store.mu.Unlock()
	defer store.active.Done()
	var fresh capturedSource
	if !exists {
		fresh = store.capture(path, entry, read)
	}
	select {
	case <-store.ctx.Done():
		return capturedSource{}, false, store.ctx.Err()
	case <-entry.ready:
	}
	if entry.err != nil {
		return capturedSource{}, false, entry.err
	}
	if !entry.ok {
		return capturedSource{}, false, nil
	}
	if !exists {
		// The first consumer already owns the bytes read from the confined source.
		// A successful spill retains only backing in the store; reading it back
		// here would duplicate I/O and allocation before parsing those same bytes.
		return fresh, true, nil
	}
	source := entry.source
	if entry.backing != "" {
		// Close waits for active readers, so the held root cannot disappear here.
		file, err := store.root.Open(entry.backing)
		if err != nil {
			return capturedSource{}, false, err
		}
		bytes, err := io.ReadAll(io.LimitReader(file, entry.size+1))
		err = errors.Join(err, file.Close())
		if err != nil {
			return capturedSource{}, false, err
		}
		if int64(len(bytes)) != entry.size || contentHash(bytes) != source.digest {
			return capturedSource{}, false, errors.New("captured source backing integrity mismatch")
		}
		source.content = string(bytes)
	}
	return source, true, nil
}

func (store *capturedStore) capture(path string, entry *captureEntry, read contentReader) (fresh capturedSource) {
	defer func() {
		if entry.err != nil {
			entry.source.content = ""
		}
		close(entry.ready)
	}()
	content, ok := read(path)
	if err := store.ctx.Err(); err != nil {
		entry.err = err
		return
	}
	entry.ok = ok
	if !ok {
		return
	}
	entry.source = captureSource(path, content)
	fresh = entry.source
	entry.size = int64(len(content))
	store.mu.Lock()
	defer store.mu.Unlock()
	if entry.size <= store.limit-store.memory {
		store.memory += entry.size
		return
	}
	if store.root == nil {
		directory, err := os.MkdirTemp("", "entire-graph-capture-")
		if err != nil {
			entry.err = fmt.Errorf("create capture backing: %w", err)
			return
		}
		root, err := os.OpenRoot(directory)
		if err != nil {
			_ = os.Remove(directory)
			entry.err = err
			return
		}
		store.root, store.directory = root, directory
	}
	store.nextBacking++
	name := strconv.Itoa(store.nextBacking) + "-" + entry.source.digest
	file, err := store.root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		entry.err = err
		return
	}
	_, writeErr := io.WriteString(file, content)
	entry.err = errors.Join(writeErr, file.Close())
	if entry.err != nil {
		_ = store.root.Remove(name)
		return
	if err != nil {
		return nil, fmt.Errorf("read %s %q: %w", label, file, err)
	}
	defer opened.Close()
	return readOpenedBoundedRegularFile(opened, expected, file, label, limit)
}

// readWorktreeNestedIgnore applies the bounded ignore reader to a
// repository-confined path. Root.Lstat refuses an ancestor symlink that escapes
// repo and identifies a leaf symlink without following it. The subsequent open
// is performed through the same root, so an ancestor swap cannot redirect it
// outside the repository; it retains the non-blocking, fstat, identity, and
// post-read growth checks used by every other external ignore input.
func readWorktreeNestedIgnore(root *os.Root, repo, candidate string) (string, bool, error) {
	candidate = filepath.ToSlash(candidate)
	if candidate == "" || path.IsAbs(candidate) || path.Clean(candidate) != candidate ||
		candidate == ".." || strings.HasPrefix(candidate, "../") ||
		!strings.HasSuffix(candidate, "/.gitignore") {
		return "", false, fmt.Errorf("invalid nested ignore path %q", candidate)
	}
	name := filepath.FromSlash(candidate)
	if filepath.IsAbs(name) || filepath.VolumeName(name) != "" {
		return "", false, fmt.Errorf("invalid nested ignore path %q", candidate)
	}
	info, err := root.Lstat(name)
	if errors.Is(err, os.ErrNotExist) || errors.Is(err, syscall.ENOTDIR) {
		return "", false, nil
	}
	if err != nil {
		return "", false, fmt.Errorf("read nested ignore file %q: %w", candidate, err)
	}
	// Git does not follow a .gitignore symlink from the worktree. Other special
	// files are not ignore inputs either; in particular, do not open a FIFO or
	// device merely because it has this basename.
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return "", false, nil
	}
	if info.Size() > maxNestedIgnoreFileBytes {
		return "", false, fmt.Errorf(
			"read nested ignore file %q: file exceeds %d bytes",
			candidate,
			maxNestedIgnoreFileBytes,
		)
	}
	full := filepath.Join(repo, name)
	opened, err := openRootBoundedRegularFile(root, name)

