			return capturedSource{}, false, errors.New("captured source backing integrity mismatch")
		}
		source.content = string(bytes)
	}
	return source, true, nil
}

func (store *capturedStore) capture(path string, entry *captureEntry, read contentReader) (fresh capturedSource) {
	defer func() {
