// no qrels, hosted models, embeddings, or network access.
// SearchRepository stamps the response envelope version at the ONE place a
// content-bearing SearchResponse leaves this package, rather than at each
// construction site. searchRepository has two success returns and error returns
// throughout; stamping per site means a third success path added later silently
// emits format_version 0, which a consumer cannot tell from "field absent".
// This mirrors how AnalyzeGitRangeWithOptions stamps SchemaVersion.
func SearchRepository(ctx context.Context, repo, providerVersion, query string, options SearchOptions) (SearchResponse, error) {
	response, err := searchRepository(ctx, repo, providerVersion, query, options)
	if err != nil {
		return SearchResponse{}, err
	}
	response.FormatVersion = SearchFormatVersion
	return response, nil
}

func searchRepository(ctx context.Context, repo, providerVersion, query string, options SearchOptions) (response SearchResponse, resultErr error) {
	var manifestPaths []string
	q := buildSearchQuery(query)
	if len(q.terms) == 0 {
		return SearchResponse{}, errors.New("search query has no meaningful terms")
	}
	if options.TopK <= 0 {
		options.TopK = defaultSearchTopK
	}
	if options.ContextLines < 0 {
		return SearchResponse{}, errors.New("search context lines cannot be negative")
	}
	if options.ContextLines == 0 {
		options.ContextLines = defaultSearchContextLines
	}
	if options.MaxRegionLines <= 0 {
		options.MaxRegionLines = defaultSearchMaxRegionLines
	}
	if options.MaxSnippetLines <= 0 {
		options.MaxSnippetLines = defaultSearchMaxSnippetLines
	}
	if options.MaxRegionsPerFile <= 0 {
		options.MaxRegionsPerFile = defaultSearchMaxRegionsPerFile
	}
	if options.MaxIndexedFiles <= 0 {
		options.MaxIndexedFiles = defaultSearchIndexedFiles(options.TopK)
		options.progressivePreselection = options.MaxIndexedFiles == defaultSearchMaxIndexedFiles
	} else {
		options.progressivePreselection = false
	}
	if options.Profile == "" {
		// Fast, not syntax-only: graph-aware ranking (caller-degree boosts and
		// relation expansion) needs call/construct edges over the indexed
		// subset. Syntax-only emits none, which silently disables the graph
		// half of hybrid search (graph_candidates is always 0).
		options.Profile = ProfileFast
	}
	sparseQuery := buildSparseSearchQueryExpanded(query, q)
	searchStarted := time.Now()
	if options.Ranking != "" && options.Ranking != "current" && options.Ranking != "experimental-graph" {
		return SearchResponse{}, errors.New("ranking must be current or experimental-graph")
	}
	if options.ExtractionReuse && options.Worktree && !options.IndexAllFiles && options.Compiler == nil && options.Ranking != "experimental-graph" && !options.rankingEvaluationCapture {
		var captureErr error
		options.preselectionCapture, captureErr = newCaptureSearchPreselectionObserver(ctx, q, resolveMaxParseBytes(options.MaxParseBytes))
		if captureErr != nil {
			return SearchResponse{}, captureErr
		}
	}
	baseSnapshotOptions := ProviderSnapshotOptions{
		captureInputs:      (options.Ranking == "experimental-graph" || options.rankingEvaluationCapture),
		Compiler:           options.Compiler,
		ExtractionReuse:    options.ExtractionReuse,
		ExtractionCacheDir: options.CacheDir,
		NoNetwork:          true,
		Worktree:           options.Worktree,
		IgnoreFiles:        options.IgnoreFiles,
		IncludeFiles:       options.IncludeFiles,
		MaxParseBytes:      options.MaxParseBytes,
		Profile:            options.Profile,
	}
	if options.preselectionCapture != nil {
		baseSnapshotOptions.captureObserverFactory = options.preselectionCapture.factory
	}
	searchCacheDisabled := options.DisableCache || options.ExtractionReuse || options.Compiler != nil || (options.Ranking == "experimental-graph" || options.rankingEvaluationCapture)
	if !options.Worktree && !searchCacheDisabled && options.CacheDir != "" {
		capturedOptions, captureErr := CaptureProviderCachePolicy(repo, baseSnapshotOptions)
		if captureErr != nil {
			// Capturing retains every policy input at once and therefore has a
			// stricter aggregate bound than sequential matcher construction. An
			// optional cache must not reject a search that the uncached path can
			// safely execute.
			searchCacheDisabled = true
		} else {
			baseSnapshotOptions = capturedOptions
		header.Tree != tree ||
		header.RepoKey != repositoryKey ||
		header.Provider != ProviderName ||
		header.ProviderVersion != providerVersion ||
		header.Profile != string(options.Profile) {
		return fmt.Errorf(
			"got schema %q repo %q tree %q provider %q version %q profile %q; want schema %q repo %q tree %q provider %q version %q profile %q",
			header.SchemaVersion, header.RepoKey, header.Tree, header.Provider, header.ProviderVersion, header.Profile,
			SchemaVersion, repositoryKey, tree, ProviderName, providerVersion, options.Profile,
		)
	}
	return nil
}

func newCachedSearchSnapshot(providerVersion, commit, tree string, options ProviderSnapshotOptions, snapshot ProviderSnapshot) cachedSearchSnapshot {
	return newCachedSearchSnapshotFrom(providerVersion, commit, tree, "", options, snapshot)
}

func newCachedSearchSnapshotFrom(providerVersion, commit, tree, derivedFrom string, options ProviderSnapshotOptions, snapshot ProviderSnapshot) cachedSearchSnapshot {
	cache := cachedSearchSnapshot{
		DerivedFrom:     derivedFrom,
		CacheVersion:    searchSnapshotCacheVersion,
		ProviderVersion: providerVersion,
		Commit:          commit,
		Tree:            tree,
		Profile:         options.Profile,
		MaxParseBytes:   options.MaxParseBytes,
		Worktree:        options.Worktree,
		Snapshot:        snapshot,
	}
	for _, file := range snapshot.Files {
		if file.Lines == 0 {
			continue
		}
		if cache.FileLines == nil {
			cache.FileLines = make(map[string]int)
		}
		cache.FileLines[file.ID] = file.Lines
	}
	for _, symbol := range snapshot.Symbols {
		if symbol.Local {
			cache.LocalSymbolIDs = append(cache.LocalSymbolIDs, symbol.ID)
		}
		if symbol.bodyless {
			cache.BodylessSymbolIDs = append(cache.BodylessSymbolIDs, symbol.ID)
		}
		if symbol.sourceEndByte > symbol.sourceStartByte {
			if cache.SymbolByteRanges == nil {
				cache.SymbolByteRanges = make(map[string]cachedSymbolByteRange)
			}
			cache.SymbolByteRanges[symbol.ID] = cachedSymbolByteRange{
				Start: symbol.sourceStartByte,
				End:   symbol.sourceEndByte,
			}
		}
		if symbol.parameterNamesKnown {
			cache.SymbolParameterNamesKnownIDs = append(cache.SymbolParameterNamesKnownIDs, symbol.ID)
		}
		if symbol.signatureTypesKnown {
			if cache.SymbolSignatureTypes == nil {
				cache.SymbolSignatureTypes = make(map[string]cachedSignatureTypes)
			}
			cache.SymbolSignatureTypes[symbol.ID] = cachedSignatureTypes{
				Params:  symbol.paramTypeText,
				Returns: symbol.returnTypeText,
			}
		}
		if len(symbol.parameterNames) > 0 {
			if cache.SymbolParameterNames == nil {
				cache.SymbolParameterNames = make(map[string][]string)
			}
			cache.SymbolParameterNames[symbol.ID] = append([]string(nil), symbol.parameterNames...)
		}
	}
	return cache
}

func restoreCachedSearchInternals(cache *cachedSearchSnapshot) {
	for index := range cache.Snapshot.Files {
		cache.Snapshot.Files[index].Lines = cache.FileLines[cache.Snapshot.Files[index].ID]
	}
	localIDs := make(map[string]bool, len(cache.LocalSymbolIDs))
	for _, id := range cache.LocalSymbolIDs {
		localIDs[id] = true
	}
	bodylessIDs := make(map[string]bool, len(cache.BodylessSymbolIDs))
	for _, id := range cache.BodylessSymbolIDs {
		bodylessIDs[id] = true
	}
	parameterNamesKnownIDs := make(map[string]bool, len(cache.SymbolParameterNamesKnownIDs))
	for _, id := range cache.SymbolParameterNamesKnownIDs {
		parameterNamesKnownIDs[id] = true
	}
	for index := range cache.Snapshot.Symbols {
		symbol := &cache.Snapshot.Symbols[index]
		symbol.Local = localIDs[symbol.ID]
		symbol.bodyless = bodylessIDs[symbol.ID]
		if sourceRange, ok := cache.SymbolByteRanges[symbol.ID]; ok && sourceRange.End > sourceRange.Start {
			symbol.sourceStartByte = sourceRange.Start
			symbol.sourceEndByte = sourceRange.End
		}
		symbol.parameterNames = append([]string(nil), cache.SymbolParameterNames[symbol.ID]...)
		symbol.parameterNamesKnown = parameterNamesKnownIDs[symbol.ID]
		if types, ok := cache.SymbolSignatureTypes[symbol.ID]; ok {
			symbol.paramTypeText = types.Params
			symbol.returnTypeText = types.Returns
			symbol.signatureTypesKnown = true
		}
	}
}

