	if (S_ISDIR(info->st_mode)) return entire_graph_metadata_directory;
	if (S_ISLNK(info->st_mode)) return entire_graph_metadata_redirect;
	if (S_ISSOCK(info->st_mode)) return entire_graph_metadata_socket;
