func searchSnapshotMatchesSelection(snapshot ProviderSnapshot, selection searchFileSelection) bool {
	return snapshot.Header.Tree == selection.tree && snapshot.Header.RepoKey == selection.repoKey
}

func searchSnapshotIdentityError(snapshot ProviderSnapshot, selection searchFileSelection) error {
	return fmt.Errorf(
		"repository identity or HEAD changed during search; retry against a stable repository (tree_match=%t repo_key_match=%t snapshot_tree=%q selection_tree=%q)",
		snapshot.Header.Tree == selection.tree,
		snapshot.Header.RepoKey == selection.repoKey,
		snapshot.Header.Tree,
		selection.tree,
	)
}

func searchTermsSafeForGitGrep(terms []string) bool {
	for _, term := range terms {
		for index := 0; index < len(term); index++ {
			if term[index] < 0x20 || term[index] > 0x7e {
				return false
			}
		}
	}
	return true
}

